WITH lines AS (SELECT id, service, host, log_ts, level, latency_ms, k, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS k, v), with_windows AS (SELECT id, host, level, latency_ms, PERCENT_RANK() OVER (PARTITION BY host ORDER BY latency_ms DESC) latency_ms_percent_rank, RANK() OVER (PARTITION BY k ORDER BY latency_ms ASC) latency_ms_rank FROM lines WHERE service IN ('checkout', 'auth')), scored AS (SELECT id, host, level, latency_ms, latency_ms_rank, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY level), 4) latency_ms_share, DENSE_RANK() OVER (PARTITION BY level ORDER BY latency_ms DESC NULLS FIRST) latency_ms_dense_rank, STDDEV_SAMP(latency_ms) OVER (PARTITION BY level) level_stddev_samp_latency_ms FROM with_windows), remaining_keys AS (SELECT id, host FROM scored EXCEPT SELECT id, host FROM app_logs WHERE host IN ('h1', 'h2', 'h4')), reconciled AS (SELECT s.* FROM scored s JOIN remaining_keys k ON s.id = k.id AND s.host = k.host), valid AS (SELECT *, CASE WHEN host IN ('h3', 'h2') THEN 'Core' ELSE 'Other' END host_group FROM reconciled WHERE level_stddev_samp_latency_ms != 702), matched_keys AS (SELECT host, id FROM valid INTERSECT ALL SELECT host, id FROM app_logs WHERE host NOT IN ('h4', 'h1', 'h3')), reconciled_app_logs AS (SELECT s.* FROM valid s JOIN matched_keys k ON s.host = k.host AND s.id = k.id) SELECT id, level, latency_ms, latency_ms_dense_rank, level_stddev_samp_latency_ms, CASE WHEN level RLIKE '^(WARN|DEBUG)$' THEN 'PRIORITY' ELSE 'CORE' END AS level_zone FROM reconciled_app_logs ORDER BY latency_ms_dense_rank DESC NULLS LAST, level_zone ASC
